<!-- 文件职责 / File responsibility: 以图形卡片和统一数值控件编辑肚皮。 / Edits belly geometry with visual cards and registry-driven controls. -->
<script setup lang="ts">
import StudioNumericControl from './StudioNumericControl.vue';import { PET_BELLY_SHAPES,createDefaultPetCustomization } from '~/domain/pet-part-customization';import type { StudioControlPath } from '~/domain/studio-control-registry';import { usePetAppearanceStore } from '~/stores/pet-appearance';const store=usePetAppearanceStore();const design=computed(()=>store.recipe.customization.belly);const colors=computed(()=>store.recipe.customization.colors);type K=Exclude<keyof typeof design.value,'visible'|'shape'>;const controls:Array<[StudioControlPath,K]>=[['customization.belly.width','width'],['customization.belly.height','height'],['customization.belly.offsetX','offsetX'],['customization.belly.offsetY','offsetY'],['customization.belly.rotation','rotation'],['customization.belly.softness','softness']];function choose(shape:typeof PET_BELLY_SHAPES[number]['id']){store.checkpoint();design.value.shape=shape;design.value.visible=true;store.markDirty()}function reset(){store.checkpoint();const d=createDefaultPetCustomization(store.recipe);Object.assign(design.value,d.belly);colors.value.belly=d.colors.belly;store.markDirty()}
</script>
<template><section class="card"><header><div><small>BELLY PATCH</small><h3>肚皮形状</h3></div><button @click="reset">恢复椭圆默认</button></header><label class="switch"><input v-model="design.visible" type="checkbox" @focus="store.checkpoint" @change="store.markDirty"><span><strong>显示肚皮</strong><small>关闭不会删除参数。</small></span></label><div class="shapes" :data-disabled="!design.visible"><button v-for="shape in PET_BELLY_SHAPES" :key="shape.id" :class="{active:design.shape===shape.id}" :disabled="!design.visible" @click="choose(shape.id)"><i :data-shape="shape.id"/><span><strong>{{shape.label}}</strong><small>{{shape.description}}</small></span></button></div><fieldset :disabled="!design.visible"><label class="color">肚皮颜色<input v-model="colors.belly" type="color" @focus="store.checkpoint" @input="store.markDirty"></label><StudioNumericControl v-for="[path,key] in controls" :key="path" :path="path" :model-value="design[key]" :disabled="!design.visible" @update:model-value="design[key]=$event"/></fieldset></section></template>
<style scoped>.card{display:grid;gap:11px;padding:13px;border:1px solid #ffffff18;border-radius:15px;background:#0d1222}header{display:flex;justify-content:space-between}header small{color:#777f9f;font:800 8px ui-monospace}h3{margin:4px 0 0}header button{border:1px solid #ffffff1f;border-radius:8px;color:#fff;background:#ffffff08}.switch{display:flex;gap:8px}.switch span{display:grid}.switch small,.shapes small{color:#8d96b7;font-size:9px}.shapes{display:grid;grid-template-columns:repeat(2,1fr);gap:7px}.shapes[data-disabled=true]{opacity:.4}.shapes button{display:flex;gap:8px;align-items:center;min-height:56px;border:1px solid #ffffff18;border-radius:9px;color:#fff;text-align:left;background:#080d18}.shapes button.active{border-color:#52e0d0}.shapes i{width:30px;height:38px;border-radius:50%;background:#f1f4ff}.shapes i[data-shape=shield]{clip-path:polygon(5% 0,95% 0,90% 55%,50% 100%,10% 55%)}.shapes i[data-shape=heart]{clip-path:polygon(50% 100%,5% 45%,15% 10%,50% 28%,85% 10%,95% 45%)}.shapes span{display:grid}.shapes strong{font-size:10px}fieldset{display:grid;gap:9px;margin:0;padding:0;border:0}.color{display:grid;gap:4px;color:#bbc3dc;font-size:10px}.color input{width:100%;height:34px;border:0;background:transparent}</style>
